import {
  AfterContentInit,
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  DoCheck,
  DOCUMENT,
  ElementRef,
  EmbeddedViewRef,
  EventEmitter,
  Inject,
  inject,
  Injector,
  Input,
  OnChanges,
  Optional,
  Output,
  QueryList,
  Renderer2,
  SimpleChanges,
  TemplateRef,
  ViewChild,
  ViewContainerRef,
} from '@angular/core';
import {
  ClrCommonStringsService,
  ClrExpandableAnimationDirective,
  HostWrapper,
  IfExpandService,
  LoadingListener,
} from '@clr/angular/utils';
import { combineLatest, ReplaySubject, Subscription } from 'rxjs';

import { ClrDatagridCell } from './datagrid-cell';
import { DatagridIfExpandService } from './datagrid-if-expanded.service';
import { DatagridDisplayMode } from './enums/display-mode.enum';
import { SelectionType } from './enums/selection-type';
import { DatagridTreeRowCells } from './interfaces/tree-row.interface';
import { ColumnsService } from './providers/columns.service';
import { DetailService } from './providers/detail.service';
import { DisplayModeService } from './providers/display-mode.service';
import { ExpandableRowsCount } from './providers/global-expandable-rows';
import { Items } from './providers/items';
import { RowActionService } from './providers/row-action-service';
import { Selection } from './providers/selection';
import { DatagridTreeService } from './providers/tree.service';
import { WrappedRow } from './wrapped-row';

let nbRow = 0;

@Component({
  selector: 'clr-dg-row',
  templateUrl: './datagrid-row.html',
  host: {
    '[class.datagrid-row]': 'true',
    '[class.datagrid-row-skeleton]': 'skeletonLoading',
    '[class.datagrid-selected]': 'selected',
    '[attr.aria-owns]': 'id',
    role: 'rowgroup',
  },
  providers: [
    DatagridIfExpandService,
    { provide: IfExpandService, useExisting: DatagridIfExpandService },
    { provide: LoadingListener, useExisting: DatagridIfExpandService },
  ],
  standalone: false,
  changeDetection: ChangeDetectionStrategy.Eager,
})
export class ClrDatagridRow<T = any> implements OnChanges, DoCheck, AfterContentInit, AfterViewInit {
  @Output('clrDgSelectedChange') selectedChanged = new EventEmitter<boolean>(false);
  @Output('clrDgExpandedChange') expandedChange = new EventEmitter<boolean>(false);
  @Input('clrDgDetailDisabled') detailDisabled = false;
  @Input('clrDgDetailHidden') detailHidden = false;
  @Input('clrDgSkeletonLoading') skeletonLoading = false;

  /**
   * In a tree, whether the row can have children, like `clrExpandable` on a tree node, so that rows
   * known to have none don't offer the toggle. A row also stops offering it when its children come
   * back empty.
   */
  @Input({ alias: 'clrDgTreeExpandable', transform: booleanAttribute }) treeExpandable = true;

  id: string;
  radioId: string;
  checkboxId: string;
  expandableId: string;
  replaced: boolean;
  displayCells = false;
  expandAnimationTrigger = false;

  /* reference to the enum so that template can access */
  SELECTION_TYPE = SelectionType;

  /**
   * @internal
   */
  itemChanges = new ReplaySubject<T>(1);

  /*****
   * property dgCells
   *
   * @description
   * A Query List of the ClrDatagrid cells in this row.
   *
   */
  @ContentChildren(ClrDatagridCell) dgCells: QueryList<ClrDatagridCell>;

  @ViewChild(ClrExpandableAnimationDirective) expandAnimation: ClrExpandableAnimationDirective;
  @ViewChild('detailButton') detailButton: ElementRef<HTMLButtonElement>;
  @ViewChild('stickyCells', { read: ViewContainerRef }) _stickyCells: ViewContainerRef;
  @ViewChild('pinnedCells', { read: ViewContainerRef }) _pinnedCells: ViewContainerRef;
  @ViewChild('scrollableCells', { read: ViewContainerRef }) _scrollableCells: ViewContainerRef;
  @ViewChild('calculatedCells', { read: ViewContainerRef }) _calculatedCells: ViewContainerRef;
  @ViewChild('fixedCellTemplate') _fixedCellTemplate: TemplateRef<any>;

  protected readonly tree = inject<DatagridTreeService<T>>(DatagridTreeService, { optional: true });

  private _item: T;
  private _selected = false;
  private _detailOpenLabel = '';
  private _detailCloseLabel = '';
  private _rowSelectionLabel = '';
  private wrappedInjector: Injector;
  /** What `_tree` worked out in this check; `undefined` until it is read. */
  private treeCells: DatagridTreeRowCells<T> | null | undefined;
  private subscriptions: Subscription[] = [];

  /**
   * The placeholder cells we create from `fixedCellTemplate` for the calculate pass. Unlike the
   * cell views, which belong to their `WrappedCell`, these are created here on every pass, so
   * they are ours to destroy. Detaching them from the container only unlinks them - the views
   * themselves would stay alive and keep the whole row, and the datagrid with it, in memory.
   */
  private fixedCellViews: EmbeddedViewRef<void>[] = [];

  // By default, every item is selectable; it becomes not selectable only if it's explicitly set to false
  private _selectable: boolean | string = true;

  // The expanded state in a tree, kept to be applied to the item when it is set, like the selectable state.
  private _treeExpanded: boolean | undefined;

  constructor(
    @Optional() public selection: Selection<T>,
    @Optional() public rowActionService: RowActionService,
    @Optional() public globalExpandable: ExpandableRowsCount,
    public expand: DatagridIfExpandService,
    @Optional() public detailService: DetailService,
    @Optional() private displayMode: DisplayModeService,
    private vcr: ViewContainerRef,
    renderer: Renderer2,
    public el: ElementRef<HTMLElement>,
    public commonStrings: ClrCommonStringsService,
    @Optional() private items: Items,
    @Optional() private columnsService: ColumnsService,
    @Inject(DOCUMENT) private document: any
  ) {
    if (
      !selection ||
      !rowActionService ||
      !globalExpandable ||
      !detailService ||
      !displayMode ||
      !items ||
      !columnsService
    ) {
      throw new Error('clr-dg-row should only be used inside of clr-datagrid');
    }
    nbRow++;
    this.id = 'clr-dg-row' + nbRow;
    this.radioId = 'clr-dg-row-rd' + nbRow;
    this.checkboxId = 'clr-dg-row-cb' + nbRow;
    this.expandableId = expand.expandableId;

    this.subscriptions.push(
      combineLatest(expand.replace, expand.expandChange).subscribe(([expandReplaceValue, expandChangeValue]) => {
        if (expandReplaceValue && expandChangeValue) {
          // replaced and expanding
          this.replaced = true;
          renderer.addClass(el.nativeElement, 'datagrid-row-replaced');
        } else {
          this.replaced = false;
          // Handles these cases: not replaced and collapsing & replaced and
          // collapsing and not replaced and expanding.
          renderer.removeClass(el.nativeElement, 'datagrid-row-replaced');
        }
      })
    );
    if (this.tree) {
      // In a tree, the rows report their expanded state like expandable rows do.
      this.subscriptions.push(
        this.tree.expandedChange.subscribe(({ item, expanded }) => {
          if (this.item !== undefined && this.tree.identify(item) === this.tree.identify(this.item)) {
            this.expandedChange.emit(expanded);
          }
        })
      );
    }
  }

  /**
   * Model of the row, to use for selection
   */
  @Input('clrDgItem')
  get item(): T {
    return this._item;
  }
  set item(item: T) {
    this._item = item;
    this.itemChanges.next(item);
    this.clrDgSelectable = this._selectable;
  }

  @Input('clrDgSelectable')
  get clrDgSelectable() {
    return !this.selection.isLocked(this.item);
  }
  set clrDgSelectable(value: boolean | string) {
    if (this.item) {
      this.selection.lockItem(this.item, value === 'false' || value === false);
    }
    // Store this value locally, to be initialized when item is initialized
    this._selectable = value;
  }

  /**
   * Indicates if the row is selected
   */
  @Input('clrDgSelected')
  get selected() {
    if (this.selection.selectionType === SelectionType.None) {
      return this._selected;
    } else {
      return this.selection.isSelected(this.item);
    }
  }
  set selected(value: boolean | string) {
    if (this.selection.selectionType === SelectionType.None) {
      this._selected = value as boolean;
    } else {
      if (this.tree?.cascading && this.item !== undefined) {
        // In a tree, a row's selection reaches its descendants and ancestors; ranges don't apply.
        this.selection.rangeStart = null;
        this.tree.setSelected([this.item], !!value);
        return;
      }
      if (value && this.selection.selectionType === SelectionType.Multi) {
        this.rangeSelect();
      } else {
        this.selection.rangeStart = null;
      }
      this.selection.setSelected(this.item, value as boolean);
    }
  }

  /**
   * Whether the row is expanded: its detail row, or in a tree, its children.
   */
  @Input('clrDgExpanded')
  get expanded() {
    const node = this._tree?.node;
    return node ? node.expanded : this.expand.expanded;
  }
  set expanded(value: boolean | string) {
    if (this.tree?.enabled()) {
      // Applied once all the inputs are set.
      this._treeExpanded = value as boolean;
    } else {
      this.expand.expanded = value as boolean;
    }
  }

  @Input()
  get clrDgDetailOpenLabel(): string {
    return this._detailOpenLabel ? this._detailOpenLabel : this.commonStrings.keys.open;
  }
  set clrDgDetailOpenLabel(label: string) {
    this._detailOpenLabel = label;
  }

  @Input()
  get clrDgDetailCloseLabel(): string {
    return this._detailCloseLabel ? this._detailCloseLabel : this.commonStrings.keys.close;
  }
  set clrDgDetailCloseLabel(label: string) {
    this._detailCloseLabel = label;
  }

  // CDE-151: Rename this field to clrDgRowSelectionLabel in v16
  @Input()
  get clrDgRowSelectionLabel(): string {
    return this._rowSelectionLabel ? this._rowSelectionLabel : this.commonStrings.keys.select;
  }
  set clrDgRowSelectionLabel(label: string) {
    this._rowSelectionLabel = label;
  }

  get _view() {
    return this.wrappedInjector.get(WrappedRow, this.vcr).rowView;
  }

  get identifyBy() {
    return this.items.identifyBy;
  }

  /**
   * What the cells of this row render of the tree, when the datagrid renders one. The row and its
   * cells read it many times per check, so it is worked out at the first read of each check.
   *
   * The cells read it while they are checked, which can be before the row's own content hooks run,
   * when the cells are rendered in a loop inside the row; the row's `ngDoCheck` runs before them.
   */
  get _tree(): DatagridTreeRowCells<T> | null {
    if (this.treeCells === undefined) {
      this.treeCells = this.workOutTreeCells();
    }
    return this.treeCells;
  }

  /**
   * Some, but not all, of this row's descendants are selected.
   */
  protected get treeIndeterminate(): boolean {
    return !!this.tree?.cascading && this.item !== undefined && this.tree.isIndeterminate(this.item);
  }

  openDetails(event: MouseEvent, detailButton: HTMLButtonElement) {
    event.stopPropagation();

    this.detailService.toggle(this.item, detailButton);
  }

  ngOnChanges(changes: SimpleChanges) {
    const treeInputs =
      changes['item'] || changes['treeExpandable'] || changes['clrDgSelectable'] || changes['expanded'];
    if (!treeInputs || !this.tree?.enabled() || this.item === undefined) {
      return;
    }
    this.tree.rowDeclared(this.item, {
      expandable: this.treeExpandable,
      locked: !this.clrDgSelectable,
      expanded: changes['item'] || changes['expanded'] ? this._treeExpanded : undefined,
    });
  }

  ngOnInit() {
    this.wrappedInjector = new HostWrapper(WrappedRow, this.vcr);
    this.selection.lockItem(this.item, this.clrDgSelectable === false);
  }

  ngDoCheck() {
    this.treeCells = undefined;
  }

  ngAfterContentInit() {
    this.markTreeCell();
    this.dgCells.changes.subscribe(() => {
      this.markTreeCell();
      this.insertCellViews();
    });
  }

  ngAfterViewInit() {
    this.subscriptions.push(
      this.displayMode.view.subscribe(viewChange => {
        // Listen for view changes and move cells around depending on the current displayType
        // remove cell views from display view
        for (let i = this._scrollableCells.length; i > 0; i--) {
          this._scrollableCells.detach();
        }
        // remove cell views of pinned columns from their static container
        for (let i = this._pinnedCells.length; i > 0; i--) {
          this._pinnedCells.detach();
        }
        // remove cell views from calculated view
        this.destroyFixedCellViews();
        for (let i = this._calculatedCells.length; i > 0; i--) {
          this._calculatedCells.detach();
        }
        if (viewChange === DatagridDisplayMode.CALCULATE) {
          this.displayCells = false;
          // Inserts a fixed cell if any of these conditions are true.
          const fixedCellConditions = [
            this.selection.selectionType !== this.SELECTION_TYPE.None,
            this.rowActionService.hasActionableRow,
            this.globalExpandable.hasExpandableRow,
            this.detailService.enabled,
          ];
          fixedCellConditions.filter(Boolean).forEach(() => {
            const fixedCellView = this._fixedCellTemplate.createEmbeddedView(null);
            this.fixedCellViews.push(fixedCellView);
            this._calculatedCells.insert(fixedCellView);
          });
          this.dgCells.forEach(cell => {
            if (!cell._view.destroyed) {
              this._calculatedCells.insert(cell._view);
            }
          });
        } else {
          this.displayCells = true;
          this.insertCellViews();
        }
      }),
      this.expand.animate.subscribe(() => {
        this.expandAnimationTrigger = !this.expandAnimationTrigger;
      })
    );
  }

  ngOnDestroy() {
    this.destroyFixedCellViews();
    this.subscriptions.forEach((sub: Subscription) => sub.unsubscribe());
  }

  toggle(selected = !this.selected) {
    if (selected !== this.selected) {
      this.selected = selected;
      this.selectedChanged.emit(selected);
    }
  }

  toggleExpand(event: MouseEvent) {
    event.stopPropagation();

    if (this.expand.expandable) {
      this.expandAnimation.updateStartHeight();
      this.expanded = !this.expanded;
      this.expandedChange.emit(this.expanded);
    }
  }

  /**
   * The default behavior in Chrome and Firefox for shift-clicking on a label is to perform text-selection.
   * This prevents our intended range-selection, because this text-selection overrides our shift-click event.
   * We need to clear the stored selection range when shift-clicking. This will override the mostly unused shift-click
   * selection browser functionality, which is inconsistently implemented in browsers anyway.
   */
  clearRanges(event: MouseEvent) {
    if (this.selection.rowSelectionMode && event.shiftKey) {
      this.document.getSelection().removeAllRanges();
      // Firefox is too persistent about its text-selection behaviour. So we need to add a preventDefault();
      // We should not try to enforce this on the other browsers, though, because their toggle cycle does not get canceled by
      // the preventDefault() and they toggle the checkbox second time, effectively retrurning it to not-selected.
      if (window.navigator.userAgent.indexOf('Firefox') !== -1) {
        event.preventDefault();
        this.toggle(true);
      }
    }
  }

  /**
   * @deprecated related to clrDgRowSelection, which is deprecated
   */
  protected selectRow(selected = !this.selected, $event) {
    // The label also captures clicks that bubble up to the row event listener, causing
    // this handler to run twice. This exits early to prevent toggling the checkbox twice.
    if (!this.selection.rowSelectionMode || $event.target.tagName === 'LABEL' || !this._selectable) {
      return;
    }
    if (this.selection.selectionType === this.SELECTION_TYPE.Single) {
      this.selection.current = [this.item];
    } else {
      this.toggle(selected);
    }
  }

  private destroyFixedCellViews() {
    // On teardown Angular has already destroyed the views in our container by the time it runs our
    // `ngOnDestroy`, so only the calculate/display transition has live ones to release here.
    this.fixedCellViews.forEach(view => {
      if (!view.destroyed) {
        view.destroy();
      }
    });
    this.fixedCellViews = [];
  }

  /**
   * Projects the cells into the display containers. Cells of pinned columns go into their static
   * container so they stay visible during horizontal scroll; the rest stay scrollable. Cells are
   * matched with their column by declaration index, and iterating in that order keeps both groups
   * aligned with the header.
   */
  private insertCellViews() {
    this.dgCells.forEach((cell, index) => {
      if (cell._view.destroyed) {
        return;
      }

      const container = this.columnsService.isPinned(index) ? this._pinnedCells : this._scrollableCells;
      container.insert(cell._view);
    });
  }

  /**
   * Lets the cells of a tree row find out which of them carries the toggle. Rows of other
   * datagrids leave their cells alone, so they pay nothing for trees.
   */
  private markTreeCell() {
    const treeRow = this.tree?.enabled() ? this : null;
    this.dgCells.forEach(cell => (cell._treeRow = treeRow));
  }

  /**
   * The cells that carry the indentation and the expand toggle are those of the toggle columns, so
   * they move with their column when it is reordered or pinned. The toggle columns are the ones marked
   * with `clrDgTreeToggle`, or the first visible column when none of them is visible. The cell that
   * names the row is the first visible one as the user sees the row, so pinned cells come first: a
   * toggle in a column like Status then reads "Expand Datacenter 1", not "Expand Running". Cells
   * match columns by declaration index, as everywhere else in the datagrid.
   */
  private workOutTreeCells(): DatagridTreeRowCells<T> | null {
    // The rows the datagrid shows while more items load have no item.
    const node = this.tree?.enabled() && this.item !== undefined ? this.tree.nodeFor(this.item) : undefined;
    if (!node) {
      return null;
    }
    const columns = this.columnsService.columns;
    const marked = new Set<ClrDatagridCell>();
    let first: ClrDatagridCell | undefined;
    let pinned: ClrDatagridCell | undefined;
    this.dgCells?.forEach((cell, index) => {
      const column = columns[index];
      if (column?.value.hidden) {
        return;
      }
      first ??= cell;
      if (column?.value.pinned) {
        pinned ??= cell;
      }
      if (this.tree.toggleColumns.has(column)) {
        marked.add(cell);
      }
    });
    const toggleCells = marked.size || !first ? marked : new Set([first]);
    return { node, toggleCells, labelCell: pinned || first };
  }

  private rangeSelect() {
    const items = this.items.displayed;
    if (!items) {
      return;
    }
    const startIx = items.indexOf(this.selection.rangeStart);
    if (
      this.selection.rangeStart &&
      this.selection.current.includes(this.selection.rangeStart) &&
      this.selection.shiftPressed &&
      startIx !== -1
    ) {
      const endIx = items.indexOf(this.item);
      // Using Set to remove duplicates
      const newSelection = new Set(
        this.selection.current.concat(items.slice(Math.min(startIx, endIx), Math.max(startIx, endIx) + 1))
      );
      this.selection.current = [...newSelection];
    } else {
      // page number has changed or
      // no Shift was pressed or
      // rangeStart not yet set
      this.selection.rangeStart = this.item;
    }
  }
}
